import java.nio.file.*;import java.util.*;import java.security.*;import org.beckenburg.editor.*;import org.beckenburg.TerrainSceneNativePhysics;import org.beckenburg.LevelDefinition.Vec;
public final class RebuildStairCellPunches {
 static String hash(Path p)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(p)));}
 public static void main(String[]a)throws Exception{Path p=Path.of(a[0]);var w=StitchedHeightmapWorld.open(p);String height=hash(p.resolve("tile_0_0.png")),layers=hash(p.resolve("terrain-layers/tile_0_0.bin"));var t=AdaptiveTerrainTopology.open(w);int before=t.cutoutCount();for(String row:Files.readAllLines(Path.of(a[1]))){if(row.isBlank())continue;double[] q=Arrays.stream(row.split("\t")).mapToDouble(Double::parseDouble).toArray();TerrainFootprintCutout.punch(t,new TerrainEntranceMesh.Bounds(q[0],q[1],q[2],q[3]));}t.save();var reopened=StitchedHeightmapWorld.open(p);if(!AdaptiveTerrainTopology.open(reopened).snapshot().equals(t.snapshot()))throw new AssertionError("Punch reopen");Path cuts=p.resolve("authored-cuts.tsv");String text=Files.readString(cuts);for(String row:Files.readAllLines(Path.of(a[1]))){if(row.isBlank())continue;String entry=row+"\tconstant-rectangular-stair-cell\n";if(!text.contains(entry))text+=entry;}Files.writeString(cuts,text);var scene=new TerrainScenePackage(reopened).openScene();record C(String name,TerrainEntranceMesh.Bounds b){}var chunks=new ArrayList<C>();for(var n:scene.nodes())for(var c:n.components())if(c.type().equals(TerrainScenePackage.COMPONENT)){var q=c.properties();chunks.add(new C(q.get("chunk"),new TerrainEntranceMesh.Bounds(Double.parseDouble(q.get("boundsX0")),Double.parseDouble(q.get("boundsZ0")),Double.parseDouble(q.get("boundsX1")),Double.parseDouble(q.get("boundsZ1")))));}for(var c:chunks)TerrainScenePackage.publish(reopened,scene,c.name,c.b);var disk=StitchedHeightmapWorld.open(p);var ds=new TerrainScenePackage(disk).openScene();if(!TerrainScenePackage.inspect(disk,ds).isEmpty())throw new AssertionError("Stale scene");Files.write(p.resolve("terrain-physics.hcs2"),TerrainSceneNativePhysics.encode(disk,ds));var physics=TerrainSceneNativePhysics.load(disk,ds).physics();int controls=0;for(String line:Files.readAllLines(cuts)){if(line.isBlank())continue;double[] q=Arrays.stream(line.split("\t")).limit(4).mapToDouble(Double::parseDouble).toArray();double x=(q[0]+q[2])/2,z=(q[1]+q[3])/2;if(!physics.clearSight(new Vec(x,24,z),new Vec(x,-24,z)))throw new AssertionError("Filled prior/new hole");controls++;}if(!height.equals(hash(p.resolve("tile_0_0.png")))||!layers.equals(hash(p.resolve("terrain-layers/tile_0_0.bin"))))throw new AssertionError("Changed heights");Files.writeString(p.resolve("stair-cell-punch-verification.json"),"{\"source_height_and_layers_unchanged\":true,\"disk_reopen_verified\":true,\"prior_and_new_hole_controls\":"+controls+",\"cutouts_before\":"+before+",\"cutouts_after\":"+t.cutoutCount()+",\"physics_sha256\":\""+hash(p.resolve("terrain-physics.hcs2"))+"\"}\n");System.out.println("SAVED_RECTANGULAR_STAIR_PUNCHES "+before+" -> "+t.cutoutCount()+" controls="+controls);}
}
